# --- cherry-pick ---------------------------------------------------------------------------

if wanted pick; then
    case_ "pick: one commit" fx_branches ':' 'G cherry-pick feat~2'
    case_ "pick: -x" fx_branches ':' 'G cherry-pick -x feat~1'
    case_ "pick: a commit that adds a file" fx_branches ':' 'G cherry-pick feat'
    case_ "pick: two commits" fx_branches ':' 'G cherry-pick feat~2 feat~1'
    case_ "pick: a range" fx_branches ':' 'G cherry-pick main..feat'
    case_ "pick: a range with -x" fx_branches ':' 'G cherry-pick -x main..feat'
    case_ "pick: --no-commit" fx_branches ':' 'G cherry-pick -n feat~1'
    case_ "pick: --no-commit a range" fx_branches ':' 'G cherry-pick -n main..feat'
    case_ "pick: -q" fx_branches ':' 'G cherry-pick -q feat~1'
    case_ "pick: conflict" fx_branches ':' 'G cherry-pick clash'
    case_ "pick: conflict then continue" fx_branches 'git cherry-pick clash; printf "R1\n" > h.txt; git add h.txt' 'G cherry-pick --continue; G status'
    case_ "pick: conflict then continue unresolved" fx_branches 'git cherry-pick clash' 'G cherry-pick --continue'
    case_ "pick: conflict then abort" fx_branches 'git cherry-pick clash' 'G cherry-pick --abort'
    case_ "pick: conflict then skip" fx_branches 'git cherry-pick clash' 'G cherry-pick --skip'
    case_ "pick: conflict then quit" fx_branches 'git cherry-pick clash' 'G cherry-pick --quit'
    case_ "pick: conflict in a range then continue" fx_branches 'git cherry-pick clash feat~2; printf "R1\n" > h.txt; git add h.txt' 'G cherry-pick --continue'
    case_ "pick: range stops then skip" fx_branches 'git checkout -q clash; git cherry-pick clash..main' 'G cherry-pick --skip; G status'
    case_ "pick: range stops then abort" fx_branches 'git checkout -q clash; git cherry-pick clash..main' 'G cherry-pick --abort'
    case_ "pick: nothing in progress" fx_branches ':' 'G cherry-pick --continue; G cherry-pick --abort; G cherry-pick --skip; G cherry-pick --quit'
    case_ "pick: a commit already applied is empty" fx_branches 'git cherry-pick feat~2' 'G cherry-pick feat~2; G status'
    case_ "pick: empty then skip" fx_branches 'git cherry-pick feat~2; git cherry-pick feat~2' 'G cherry-pick --skip'
    case_ "pick: empty with --allow-empty" fx_branches 'git cherry-pick feat~2' 'G cherry-pick --allow-empty feat~2'
    case_ "pick: empty with --keep-redundant-commits" fx_branches 'git cherry-pick feat~2' 'G cherry-pick --keep-redundant-commits feat~2'
    case_ "pick: dirty work tree in the way" fx_branches 'echo x >> f.txt' 'G cherry-pick feat~2'
    case_ "pick: dirty elsewhere is fine" fx_branches 'echo x >> g.txt' 'G cherry-pick feat~2'
    case_ "pick: staged changes refuse" fx_branches 'echo x >> g.txt; git add g.txt' 'G cherry-pick feat~2'
    case_ "pick: bad revision" fx_branches ':' 'G cherry-pick nope'
    case_ "pick: no arguments" fx_branches ':' 'G cherry-pick'
    case_ "pick: a merge needs -m" fx_mergecommit 'git checkout -q other' 'G cherry-pick main~1'
    case_ "pick: a merge with -m 1" fx_mergecommit 'git checkout -q other~1' 'G cherry-pick -m 1 main~1'
    case_ "pick: a merge with -m 2" fx_mergecommit 'git checkout -q other~1' 'G cherry-pick -m 2 main~1'
    case_ "pick: -m on a plain commit" fx_mergecommit 'git checkout -q other' 'G cherry-pick -m 1 feat~1'
    case_ "pick: -m 3 does not exist" fx_mergecommit 'git checkout -q other' 'G cherry-pick -m 3 main~1'
    case_ "pick: during a merge" fx_conflict ':' 'G cherry-pick other'
    case_ "pick: author is kept, committer is ours" fx_pick 'git cherry-pick --abort' 'G cherry-pick other'
    case_ "pick: detached HEAD" fx_branches 'git checkout -q --detach' 'G cherry-pick feat~1; G cherry-pick -x feat'
    case_ "pick: from a subdirectory" fx_base 'mkdir -p dir; git checkout -q side' 'cd dir; G cherry-pick main'
    case_ "pick: the same commit twice" fx_branches ':' 'G cherry-pick feat~1 feat~1'
    case_ "pick: -n then commit" fx_branches ':' 'G cherry-pick -n feat~1; G commit -m "by hand"'
    case_ "pick: multi-line message" fx_branches 'git checkout -q feat; git commit -q --allow-empty -m "subject line" -m "body paragraph" -m "Signed-off-by: A <a@b>"; git checkout -q main' 'G cherry-pick -x feat'
    case_ "pick: -n of a commit with a conflict" fx_branches ':' 'G cherry-pick -n clash'
    case_ "pick: diff3 conflict style" fx_branches 'git config merge.conflictStyle diff3' 'G cherry-pick clash'
    case_ "pick: zdiff3 conflict style" fx_branches 'git config merge.conflictStyle zdiff3' 'G cherry-pick clash'
    case_ "pick: ranges a..b with a negative" fx_branches ':' 'G cherry-pick feat ^feat~2'
    case_ "pick: --edit with a no-op editor" fx_branches ':' 'GIT_EDITOR=true G cherry-pick --edit feat~1'
    case_ "pick: --edit with an editor that changes the message" fx_branches ':' 'GIT_EDITOR="sed -i.bak 1s/^/EDITED:/" G cherry-pick -e feat~1'
    case_ "pick: --edit with an empty message" fx_branches ':' 'GIT_EDITOR="cp /dev/null" G cherry-pick -e feat~1'
    case_ "pick: a tag" fx_branches 'git tag t1 feat~1' 'G cherry-pick t1'
    case_ "pick: --continue after commit by hand" fx_branches 'git cherry-pick clash clash feat; printf "r\n" > f.txt; git add f.txt; git commit -qm "by hand"' 'G cherry-pick --continue'
    case_ "pick: --signoff" fx_branches ':' 'G cherry-pick -s feat~1'
    case_ "pick: -x --signoff" fx_branches ':' 'G cherry-pick -x -s feat~1'
    case_ "pick: --signoff twice does not repeat" fx_branches 'git checkout -q feat; git commit -q --amend -s -m "feat: g signed" ; git checkout -q main' 'G cherry-pick -s feat'
    case_ "pick: --signoff keeps a trailer block" fx_branches 'git checkout -q feat; git commit -q --amend -m "subject" -m "Reviewed-by: Rev <r@x>" ; git checkout -q main' 'G cherry-pick -s feat'
    case_ "pick: -X theirs" fx_branches 'git checkout -q clash; printf "CLASH2\n" > h.txt; git commit -qam c2; git checkout -q main' 'G cherry-pick -X theirs clash'
    case_ "pick: -X ours" fx_branches ':' 'G cherry-pick -X ours clash'
    case_ "pick: a root commit" fx_branches 'git checkout -q -b rooted; git checkout -q --orphan r2; git rm -rfq .; echo r > r.txt; git add r.txt; git commit -qm "second root"; git checkout -q main' 'G cherry-pick r2'
fi

# --- revert --------------------------------------------------------------------------------

if wanted revert; then
    case_ "revert: one commit" fx_branches 'git cherry-pick feat~2' 'G revert --no-edit HEAD'
    case_ "revert: with an editor that keeps the message" fx_branches 'git cherry-pick feat~2' 'GIT_EDITOR=true G revert HEAD'
    case_ "revert: with an editor that edits" fx_branches 'git cherry-pick feat~2' 'GIT_EDITOR="sed -i.bak 1s/^/Edited:/" G revert HEAD'
    case_ "revert: an older commit" fx_branches 'git cherry-pick feat~2 feat~1' 'G revert --no-edit HEAD~1'
    case_ "revert: --no-commit" fx_branches 'git cherry-pick feat~2' 'G revert -n HEAD'
    case_ "revert: two commits" fx_branches 'git cherry-pick feat~2 feat~1 feat' 'G revert --no-edit HEAD HEAD~1'
    case_ "revert: a range" fx_branches 'git cherry-pick main..feat' 'G revert --no-edit HEAD~2..HEAD'
    case_ "revert: a range no commit" fx_branches 'git cherry-pick main..feat' 'G revert -n HEAD~2..HEAD'
    case_ "revert: conflict" fx_branches 'git cherry-pick feat~2; echo more >> f.txt; git commit -qam later' 'G revert --no-edit HEAD~1'
    case_ "revert: conflict then continue" fx_branches 'git cherry-pick feat~2; printf "l1\nl2\nl3\nl4\nl5\nl6\nl7\nZ8\nl9\n" > f.txt; git commit -qam later; git revert --no-edit HEAD~1; printf "resolved\n" > f.txt; git add f.txt' 'GIT_EDITOR=true G revert --continue; G status'
    case_ "revert: conflict then abort" fx_branches 'git cherry-pick feat~2; echo more >> f.txt; git commit -qam later; git revert --no-edit HEAD~1' 'G revert --abort'
    case_ "revert: conflict then skip" fx_branches 'git cherry-pick feat~2; echo more >> f.txt; git commit -qam later; git revert --no-edit HEAD~1' 'G revert --skip'
    case_ "revert: conflict then quit" fx_branches 'git cherry-pick feat~2; echo more >> f.txt; git commit -qam later; git revert --no-edit HEAD~1' 'G revert --quit'
    case_ "revert: a revert of a revert" fx_branches 'git cherry-pick feat~2; git revert --no-edit HEAD' 'G revert --no-edit HEAD'
    case_ "revert: a merge needs -m" fx_mergecommit ':' 'G revert --no-edit main~1'
    case_ "revert: a merge with -m 1" fx_mergecommit ':' 'G revert --no-edit -m 1 main~1'
    case_ "revert: a merge with -m 2" fx_mergecommit ':' 'G revert --no-edit -m 2 main~1'
    case_ "revert: the root commit" fx_branches ':' 'G revert --no-edit main~3'
    case_ "revert: a commit that is not applicable" fx_branches ':' 'G revert --no-edit feat'
    case_ "revert: dirty work tree" fx_branches 'echo x >> f.txt' 'G revert --no-edit main'
    case_ "revert: nothing in progress" fx_branches ':' 'G revert --continue; G revert --abort'
    case_ "revert: bad revision" fx_branches ':' 'G revert --no-edit nope'
    case_ "revert: --signoff" fx_branches 'git cherry-pick feat~2' 'G revert --no-edit -s HEAD'
    case_ "revert: quiet" fx_branches ':' 'G revert -q --no-edit HEAD'
    case_ "revert: subject of a revert of a revert" fx_branches 'git revert --no-edit HEAD; git revert --no-edit HEAD' 'G revert --no-edit HEAD'
    case_ "revert: detached HEAD" fx_branches 'git checkout -q --detach' 'G revert --no-edit HEAD'
fi
